function apiError(status, detail) {
  const error = new Error(typeof detail === "string" ? detail : detail?.message || "Erro no Firebase");
  error.response = { status, data: { detail } };
  return error;
}

function clean(value) {
  if (Array.isArray(value)) return value.map(clean).filter((item) => item !== undefined);
  if (value && typeof value === "object" && !(value instanceof Date)) {
    return Object.fromEntries(Object.entries(value).filter(([, item]) => item !== undefined).map(([key, item]) => [key, clean(item)]));
  }
  return value;
}

function id() {
  return globalThis.crypto?.randomUUID?.() || push(ref(firebaseDb, "_ids")).key;
}

function now() { return new Date().toISOString(); }

async function context() {
  const authUser = firebaseAuth.currentUser;
  if (!authUser) throw apiError(401, "Sessão expirada.");
  const profile = (await get(ref(firebaseDb, `usuarios/${authUser.uid}`))).val() || {};
  return { authUser, profile, tenantId: profile.tenant_id || "kuryos" };
}

function collectionPath(tenantId, collection) { return `${ROOT}/${tenantId}/${collection}`; }

async function all(tenantId, collection) {
  const value = (await get(ref(firebaseDb, collectionPath(tenantId, collection)))).val() || {};
  return Object.entries(value).map(([key, item]) => ({ id: item?.id || key, ...(item || {}) }));
}

async function one(tenantId, collection, itemId) {
  const value = (await get(ref(firebaseDb, `${collectionPath(tenantId, collection)}/${itemId}`))).val();
  return value ? { id: value.id || itemId, ...value } : null;
}

async function save(tenantId, collection, itemId, value) {
  const document = clean({ ...value, id: itemId, tenant_id: tenantId });
  await set(ref(firebaseDb, `${collectionPath(tenantId, collection)}/${itemId}`), document);
  return document;
}

async function patch(tenantId, collection, itemId, values) {
  const current = await one(tenantId, collection, itemId);
  if (!current) throw apiError(404, "Registro não encontrado.");
  return save(tenantId, collection, itemId, { ...current, ...clean(values), updated_at: now() });
}

async function erase(tenantId, collection, itemId) {
  await remove(ref(firebaseDb, `${collectionPath(tenantId, collection)}/${itemId}`));
}

async function create(tenantId, collection, values) {
  const itemId = id();
  return save(tenantId, collection, itemId, { ...values, created_at: values?.created_at || now(), updated_at: now() });
}

async function related(tenantId, collection, field, value) {
  return (await all(tenantId, collection)).filter((item) => item[field] === value);
}

function sortNewest(items) {
  return items.sort((a, b) => String(b.updated_at || b.created_at || "").localeCompare(String(a.updated_at || a.created_at || "")));
}

function printableBlob(title, record) {
  const html = `<!doctype html><meta charset="utf-8"><title>${title}</title><h1>${title}</h1><pre>${JSON.stringify(record, null, 2)}</pre>`;
  return new Blob([html], { type: "text/html;charset=utf-8" });
}

function contains(document, query, fields) {
  if (!query) return true;
  const needle = String(query).toLocaleLowerCase("pt-BR");
  return fields.some((field) => String(field.split(".").reduce((obj, key) => obj?.[key], document) || "").toLocaleLowerCase("pt-BR").includes(needle));
}

function response(data, config) { return { data, status: 200, statusText: "OK", headers: {}, config }; }

async function listUsers() {
  const users = (await get(ref(firebaseDb, "usuarios"))).val() || {};
  return Object.entries(users).map(([uid, profile]) => ({
    id: uid, uid, name: profile.name || profile.nome || profile.email, email: profile.email, role: profile.role,
  }));
}

async function clientFull(tenantId, client) {
  const projects = (await all(tenantId, "crm_projects")).filter((item) => item.cliente_id === client.id);
  const projectIds = new Set(projects.map((item) => item.id));
  const samples = (await all(tenantId, "crm_samples")).filter((item) => projectIds.has(item.projeto_id));
  const orders = (await all(tenantId, "orders")).filter((item) => item.cliente_id === client.id);
  return {
    client, projects, samples, orders,
    summary: {
      total_projetos: projects.length,
      projetos_ativos: projects.filter((item) => !["pedido_aprovado", "projeto_arquivado"].includes(item.stage)).length,
      total_amostras: samples.length,
      item_mais_pedido: "",
    },
  };
}

async function projectFull(tenantId, project) {
  const client = await one(tenantId, "crm_clients", project.cliente_id);
  const samples = (await all(tenantId, "crm_samples")).filter((item) => item.projeto_id === project.id);
  const pdCards = (await all(tenantId, "pd_cards")).filter((item) => item.projeto_id === project.id);
  return { project, client, samples, pd_cards: pdCards, orders: [] };
}

async function createPdFlow(tenantId, sample, variation, project, client, profile) {
  const requestId = id();
  const developmentId = id();
  const cardId = id();
  const createdAt = now();
  const request = await save(tenantId, "pd_requests", requestId, {
    project_name: sample.nome_produto || sample.nome_amostra,
    title: sample.nome_produto || sample.nome_amostra,
    client_id: client?.id || "",
    client_name: client?.nome_empresa || sample.cliente_nome || "",
    crm_project_id: project?.id || sample.projeto_id,
    crm_sample_id: sample.id,
    crm_variacao_id: variation.id,
    status: "OPEN",
    priority: sample.prioridade || "Normal",
    request_type: "CLIENT",
    created_by: firebaseAuth.currentUser?.uid,
    created_by_name: profile.nome || profile.name || profile.email,
    created_at: createdAt,
    updated_at: createdAt,
  });
  await save(tenantId, "pd_developments", developmentId, {
    request_id: requestId, status: "OPEN", created_at: createdAt, updated_at: createdAt,
  });
  const card = await save(tenantId, "pd_cards", cardId, {
    pd_request_id: requestId,
    development_id: developmentId,
    projeto_id: project?.id || sample.projeto_id,
    amostra_id: sample.id,
    amostra_variacao_id: variation.id,
    amostra_numero: sample.numero_amostra || "",
    titulo: request.project_name,
    nome_produto: request.project_name,
    cliente_nome: request.client_name,
    projeto_nome: project?.nome_projeto || sample.projeto_nome || "",
    status_pd: "solicitado",
    created_at: createdAt,
    updated_at: createdAt,
  });
  return { request, card };
}

async function createSamplesBatch(tenantId, payload, profile) {
  const project = await one(tenantId, "crm_projects", payload.projeto_id);
  if (!project) throw apiError(404, "Projeto não encontrado.");
  if (payload.projeto_updates) await patch(tenantId, "crm_projects", project.id, payload.projeto_updates);
  const client = await one(tenantId, "crm_clients", project.cliente_id);
  const existing = await all(tenantId, "crm_samples");
  const created = [];
  for (const source of payload.samples || []) {
    const sampleId = id();
    const sequence = existing.length + created.length + 1;
    const variations = (source.variacoes?.length ? source.variacoes : [{}]).map((variation, index) => ({
      ...variation,
      id: id(),
      codigo: `${String(sequence).padStart(4, "0")}-${String.fromCharCode(65 + index)}`,
      status: "solicitada",
      status_pd_raw: "solicitado",
      status_pd_label: "Aberto",
      created_at: now(),
    }));
    let sample = await save(tenantId, "crm_samples", sampleId, {
      ...source,
      projeto_id: project.id,
      projeto_nome: project.nome_projeto,
      cliente_id: client?.id || project.cliente_id,
      cliente_nome: client?.nome_empresa || project.cliente_nome,
      numero_amostra: `AM-${String(sequence).padStart(5, "0")}`,
      stage: "solicitada",
      variacoes: variations,
      created_at: now(),
      updated_at: now(),
    });
    for (const variation of variations) {
      const flow = await createPdFlow(tenantId, sample, variation, project, client, profile);
      variation.pd_card_id = flow.card.id;
      variation.pd_request_id = flow.request.id;
    }
    sample = await save(tenantId, "crm_samples", sampleId, { ...sample, variacoes: variations });
    created.push(sample);
  }
  return { count: created.length, samples: created };
}

async function requestFull(tenantId, request) {
  const development = (await all(tenantId, "pd_developments")).find((item) => item.request_id === request.id) || null;
  const devId = development?.id;
  const byDev = async (collection) => (await all(tenantId, collection)).filter((item) => item.development_id === devId);
  const formulas = devId ? await byDev("pd_formulas") : [];
  const formulaIds = new Set(formulas.map((item) => item.id));
  const formulaItems = (await all(tenantId, "pd_formula_items")).filter((item) => formulaIds.has(item.formula_id));
  return {
    request,
    development,
    formulas: formulas.map((formula) => ({ ...formula, items: formulaItems.filter((item) => item.formula_id === formula.id) })),
    tests: devId ? await byDev("pd_tests") : [],
    samples: devId ? await byDev("pd_samples") : [],
    approvals: devId ? await byDev("pd_approvals") : [],
    costs: devId ? await byDev("pd_costs") : [],
    documents: devId ? await byDev("pd_documents") : [],
    updates: (await all(tenantId, "pd_updates")).filter((item) => item.request_id === request.id),
    pending_items: (await all(tenantId, "pd_pending_items")).filter((item) => item.request_id === request.id),
    status_history: (await all(tenantId, "pd_request_status_history")).filter((item) => item.request_id === request.id),
    blocking_tasks: [],
  };
}

async function dispatch(method, rawUrl, data = {}, config = {}) {
  const { profile, tenantId } = await context();
  const url = new URL(rawUrl, "https://firebase.local");
  const path = url.pathname.replace(/^\/api/, "");
  const params = { ...Object.fromEntries(url.searchParams), ...(config.params || {}) };
  const match = (pattern) => path.match(pattern);

  if (method === "GET" && path === "/auth/me") return response(profile, config);
  if (method === "GET" && (path === "/crm/users-list" || path === "/users")) return response(await listUsers(), config);
  if (method === "GET" && path === "/crm/constants") return response(CRM_CONSTANTS, config);

  if (method === "GET" && path === "/crm/clients") {
    let items = await all(tenantId, "crm_clients");
    if (params.search) items = items.filter((item) => contains(item, params.search, ["nome_empresa", "cnpj", "contato_principal.nome", "contato_principal.email"]));
    return response(items.sort((a, b) => String(b.updated_at || b.created_at).localeCompare(String(a.updated_at || a.created_at))), config);
  }
  if (method === "POST" && path === "/crm/clients") {
    const itemId = id();
    return response(await save(tenantId, "crm_clients", itemId, { ...data, stage: "prospeccao", created_at: now(), updated_at: now(), created_by: firebaseAuth.currentUser.uid }), config);
  }
  let m = match(/^\/crm\/clients\/([^/]+)\/full$/);
  if (method === "GET" && m) {
    const client = await one(tenantId, "crm_clients", m[1]);
    if (!client) throw apiError(404, "Cliente não encontrado.");
    return response(await clientFull(tenantId, client), config);
  }
  m = match(/^\/crm\/clients\/([^/]+)\/move$/);
  if (method === "PUT" && m) {
    const client = await patch(tenantId, "crm_clients", m[1], { stage: data.stage, motivo_perda: data.motivo_perda, justificativa: data.justificativa });
    return response({ ...client, to_stage: data.stage }, config);
  }
  m = match(/^\/crm\/clients\/([^/]+)$/);
  if (m && method === "GET") return response(await one(tenantId, "crm_clients", m[1]), config);
  if (m && method === "PUT") return response(await patch(tenantId, "crm_clients", m[1], data), config);

  if (method === "GET" && path === "/crm/projects") {
    let items = await all(tenantId, "crm_projects");
    if (params.search) items = items.filter((item) => contains(item, params.search, ["nome_projeto", "cliente_nome", "ideia_conceito"]));
    return response(items, config);
  }
  if (method === "POST" && path === "/crm/projects/batch") {
    const client = await one(tenantId, "crm_clients", data.cliente_id);
    if (!client) throw apiError(404, "Cliente não encontrado.");
    const items = [];
    for (const source of data.projects || []) {
      const itemId = id();
      items.push(await save(tenantId, "crm_projects", itemId, { ...source, cliente_id: client.id, cliente_nome: client.nome_empresa, stage: "projeto_em_discussao", created_at: now(), updated_at: now() }));
    }
    return response({ count: items.length, projects: items }, config);
  }
  m = match(/^\/crm\/projects\/([^/]+)\/full$/);
  if (method === "GET" && m) {
    const project = await one(tenantId, "crm_projects", m[1]);
    if (!project) throw apiError(404, "Projeto não encontrado.");
    return response(await projectFull(tenantId, project), config);
  }
  m = match(/^\/crm\/projects\/([^/]+)\/move$/);
  if (method === "PUT" && m) {
    const project = await patch(tenantId, "crm_projects", m[1], { stage: data.stage, motivo_arquivamento: data.motivo_arquivamento });
    return response({ ...project, to_stage: data.stage, trigger_batch_samples: data.stage === "amostra_solicitada" }, config);
  }
  m = match(/^\/crm\/projects\/([^/]+)$/);
  if (m && method === "GET") return response(await one(tenantId, "crm_projects", m[1]), config);
  if (m && method === "PUT") return response(await patch(tenantId, "crm_projects", m[1], data), config);
  if (m && method === "DELETE") { await erase(tenantId, "crm_projects", m[1]); return response({ deleted: true }, config); }

  if (method === "POST" && ["/crm/samples/batch/v2", "/crm/samples/batch"].includes(path)) return response(await createSamplesBatch(tenantId, data, profile), config);
  if (method === "GET" && path === "/crm/samples") {
    let items = await all(tenantId, "crm_samples");
    if (params.search) items = items.filter((item) => contains(item, params.search, ["nome_produto", "nome_amostra", "numero_amostra", "cliente_nome", "projeto_nome"]));
    return response(items, config);
  }
  m = match(/^\/crm\/samples\/([^/]+)\/variacoes$/);
  if (method === "POST" && m) {
    const sample = await one(tenantId, "crm_samples", m[1]);
    if (!sample) throw apiError(404, "Amostra não encontrada.");
    const project = await one(tenantId, "crm_projects", sample.projeto_id);
    const client = project ? await one(tenantId, "crm_clients", project.cliente_id) : null;
    const variations = [...(sample.variacoes || [])];
    for (const source of data.variacoes || []) {
      const variation = { ...source, id: id(), codigo: `${sample.numero_amostra}-${String.fromCharCode(65 + variations.length)}`, status: "solicitada", status_pd_raw: "solicitado", status_pd_label: "Aberto", created_at: now() };
      const flow = await createPdFlow(tenantId, sample, variation, project, client, profile);
      variation.pd_card_id = flow.card.id;
      variation.pd_request_id = flow.request.id;
      variations.push(variation);
    }
    await patch(tenantId, "crm_samples", sample.id, { variacoes: variations });
    return response({ added: (data.variacoes || []).length, variacoes: variations }, config);
  }
  m = match(/^\/crm\/samples\/([^/]+)\/variacoes\/([^/]+)\/resultado-cliente$/);
  if (method === "POST" && m) {
    const sample = await one(tenantId, "crm_samples", m[1]);
    const variations = (sample?.variacoes || []).map((item) => item.id === m[2] ? { ...item, status: data.resultado, resultado_cliente: data.resultado, feedback_cliente: data.feedback_cliente || "", resultado_em: now() } : item);
    await patch(tenantId, "crm_samples", m[1], { variacoes: variations });
    return response({ success: true, sku_created: data.resultado === "aprovada" ? { blocked: true, reason: "Geração de SKU será habilitada com o módulo de Cadastros." } : null }, config);
  }
  m = match(/^\/crm\/samples\/([^/]+)\/variacoes\/([^/]+)$/);
  if (m && ["PUT", "DELETE"].includes(method)) {
    const sample = await one(tenantId, "crm_samples", m[1]);
    if (!sample) throw apiError(404, "Amostra não encontrada.");
    const variations = method === "DELETE" ? (sample.variacoes || []).filter((item) => item.id !== m[2]) : (sample.variacoes || []).map((item) => item.id === m[2] ? { ...item, ...data, updated_at: now() } : item);
    await patch(tenantId, "crm_samples", m[1], { variacoes: variations });
    return response({ success: true }, config);
  }
  m = match(/^\/crm\/samples\/([^/]+)$/);
  if (m && method === "GET") return response(await one(tenantId, "crm_samples", m[1]), config);
  if (m && method === "PUT") return response(await patch(tenantId, "crm_samples", m[1], data), config);
  if (m && method === "DELETE") { await erase(tenantId, "crm_samples", m[1]); return response({ deleted: true, deleted_pd_cards: 0 }, config); }

  if (method === "GET" && path === "/crm/pd/cards") {
    let items = await all(tenantId, "pd_cards");
    if (params.search) items = items.filter((item) => contains(item, params.search, ["titulo", "nome_produto", "cliente_nome", "projeto_nome"]));
    return response(items, config);
  }
  m = match(/^\/crm\/pd\/cards\/([^/]+)\/move$/);
  if (method === "PUT" && m) {
    const card = await patch(tenantId, "pd_cards", m[1], { status_pd: data.status, observacao: data.observacao });
    return response({ ...card, to_status: data.status, synced_to_crm: true }, config);
  }
  m = match(/^\/crm\/pd\/cards\/([^/]+)$/);
  if (m && method === "GET") return response(await one(tenantId, "pd_cards", m[1]), config);
  if (m && method === "PUT") return response(await patch(tenantId, "pd_cards", m[1], data), config);

  if (method === "POST" && path === "/pd/requests/internal-research") {
    const requestId = id(); const developmentId = id(); const cardId = id();
    const request = await save(tenantId, "pd_requests", requestId, { ...data, title: data.project_name, status: "OPEN", request_type: "INTERNAL", created_at: now(), updated_at: now() });
    await save(tenantId, "pd_developments", developmentId, { request_id: requestId, status: "OPEN", created_at: now(), updated_at: now() });
    await save(tenantId, "pd_cards", cardId, { pd_request_id: requestId, development_id: developmentId, titulo: data.project_name, nome_produto: data.project_name, status_pd: "solicitado", created_at: now(), updated_at: now() });
    return response(request, config);
  }
  if (method === "GET" && path === "/pd/requests") return response(await all(tenantId, "pd_requests"), config);
  m = match(/^\/pd\/requests\/([^/]+)\/full$/);
  if (method === "GET" && m) {
    const request = await one(tenantId, "pd_requests", m[1]);
    if (!request) throw apiError(404, "Requisição P&D não encontrada.");
    return response(await requestFull(tenantId, request), config);
  }
  m = match(/^\/pd\/requests\/([^/]+)\/status$/);
  if (method === "PUT" && m) {
    const request = await patch(tenantId, "pd_requests", m[1], { status: data.new_status });
    const historyId = id();
    await save(tenantId, "pd_request_status_history", historyId, { request_id: m[1], from_status: data.from_status || "", to_status: data.new_status, comment: data.comment || "", created_at: now(), user_id: firebaseAuth.currentUser.uid });
    return response(request, config);
  }
  m = match(/^\/pd\/requests\/([^/]+)$/);
  if (m && method === "GET") return response(await one(tenantId, "pd_requests", m[1]), config);
  if (m && method === "PUT") return response(await patch(tenantId, "pd_requests", m[1], data), config);
  if (m && method === "DELETE") { await erase(tenantId, "pd_requests", m[1]); return response({ deleted: true }, config); }

  if (method === "GET" && path === "/pd/formulas/bank") {
    let formulas = await all(tenantId, "pd_formulas");
    const items = await all(tenantId, "pd_formula_items");
    formulas = formulas.map((formula) => ({ ...formula, items: items.filter((item) => item.formula_id === formula.id) }));
    if (params.q) formulas = formulas.filter((item) => contains(item, params.q, ["name", "nome", "code", "codigo"]));
    return response(formulas, config);
  }
  m = match(/^\/pd\/pd-cards\/([^/]+)\/executor$/);
  if (method === "PUT" && m) return response(await patch(tenantId, "pd_cards", m[1], data), config);

  if (method === "GET" && ["/pd/clients/search", "/crm/clients/suggest-cli4"].includes(path)) {
    const q = params.q || params.nome || "";
    const clients = (await all(tenantId, "crm_clients")).filter((item) => contains(item, q, ["nome_empresa", "nome_fantasia", "cnpj"]));
    return response(clients.slice(0, Number(params.limit) || 20), config);
  }
  if (method === "GET" && path === "/crm/skus") return response(await all(tenantId, "skus"), config);
  if (method === "GET" && path === "/cadastros/materiais") return response(await all(tenantId, "materiais"), config);
  if (method === "GET" && path === "/cadastros/fragrancias") return response(await all(tenantId, "fragrancias"), config);
  if (method === "GET" && path === "/compras/fornecedores") return response(await all(tenantId, "pd_homologacao_fornecedores"), config);

  if (method === "POST" && path === "/orders/direct") return response(await create(tenantId, "orders", { ...data, origem: "crm_direto", status: "rascunho" }), config);
  m = match(/^\/orders\/reorder\/([^/]+)$/);
  if (method === "GET" && m) return response(sortNewest((await all(tenantId, "orders")).filter((item) => item.cliente_id === m[1])), config);
  m = match(/^\/crm\/projects\/([^/]+)\/proposta$/);
  if (method === "GET" && m) return response((await related(tenantId, "crm_propostas", "projeto_id", m[1]))[0] || null, config);
  if (method === "POST" && m) {
    const current = (await related(tenantId, "crm_propostas", "projeto_id", m[1]))[0];
    return response(current ? await patch(tenantId, "crm_propostas", current.id, data) : await create(tenantId, "crm_propostas", { ...data, projeto_id: m[1] }), config);
  }
  m = match(/^\/crm\/projects\/([^/]+)\/amostras-status$/);
  if (method === "GET" && m) return response((await related(tenantId, "crm_samples", "projeto_id", m[1])).map((sample) => ({ id: sample.id, numero_amostra: sample.numero_amostra, variacoes: sample.variacoes || [] })), config);
  m = match(/^\/crm\/projects\/([^/]+)\/material-requirements$/);
  if (method === "GET" && m) return response([], config);

  if (method === "POST" && path === "/pd/requests") {
    const request = await create(tenantId, "pd_requests", { ...data, title: data.title || data.project_name || data.product_name, status: data.status || "OPEN", request_type: data.request_type || "CLIENT" });
    const development = await create(tenantId, "pd_developments", { request_id: request.id, status: "OPEN" });
    await create(tenantId, "pd_cards", { pd_request_id: request.id, development_id: development.id, titulo: request.title, nome_produto: request.title, cliente_nome: request.client_name || "", status_pd: "solicitado" });
    return response(request, config);
  }

  m = match(/^\/pd\/developments\/([^/]+)\/formulas$/);
  if (method === "GET" && m) return response(await related(tenantId, "pd_formulas", "development_id", m[1]), config);
  if (method === "POST" && m) return response(await create(tenantId, "pd_formulas", { ...data, development_id: m[1], version: data.version || 1, status: data.status || "DRAFT" }), config);
  m = match(/^\/pd\/formulas\/([^/]+)\/items$/);
  if (method === "GET" && m) return response(await related(tenantId, "pd_formula_items", "formula_id", m[1]), config);
  if (method === "POST" && m) return response(await create(tenantId, "pd_formula_items", { ...data, formula_id: m[1] }), config);
  m = match(/^\/pd\/formula-items\/([^/]+)$/);
  if (method === "PUT" && m) return response(await patch(tenantId, "pd_formula_items", m[1], data), config);
  if (method === "DELETE" && m) { await erase(tenantId, "pd_formula_items", m[1]); return response({ deleted: true }, config); }
  m = match(/^\/pd\/formulas\/([^/]+)\/(duplicate|new-version)$/);
  if (method === "POST" && m) {
    const formula = await one(tenantId, "pd_formulas", m[1]);
    const copy = await create(tenantId, "pd_formulas", { ...formula, id: undefined, parent_formula_id: m[2] === "new-version" ? m[1] : formula?.parent_formula_id, name: m[2] === "duplicate" ? `${formula?.name || formula?.nome || "Formula"} - copia` : formula?.name, version: m[2] === "new-version" ? Number(formula?.version || 1) + 1 : formula?.version, justification: data.justification, status: "DRAFT" });
    for (const item of await related(tenantId, "pd_formula_items", "formula_id", m[1])) await create(tenantId, "pd_formula_items", { ...item, id: undefined, formula_id: copy.id });
    return response(copy, config);
  }
  m = match(/^\/pd\/formulas\/([^/]+)\/import-into\/([^/]+)$/);
  if (method === "POST" && m) {
    const formula = await one(tenantId, "pd_formulas", m[1]);
    const imported = await create(tenantId, "pd_formulas", { ...formula, id: undefined, development_id: m[2], source_formula_id: m[1], status: "DRAFT" });
    for (const item of await related(tenantId, "pd_formula_items", "formula_id", m[1])) await create(tenantId, "pd_formula_items", { ...item, id: undefined, formula_id: imported.id });
    return response(imported, config);
  }
  m = match(/^\/pd\/formulas\/([^/]+)\/costs$/);
  if (method === "GET" && m) return response(await related(tenantId, "pd_formula_costs", "formula_id", m[1]), config);
  if (method === "POST" && m) return response(await create(tenantId, "pd_formula_costs", { ...data, formula_id: m[1] }), config);
  m = match(/^\/pd\/formulas\/([^/]+)\/phases$/);
  if (method === "GET" && m) return response((await related(tenantId, "pd_formula_phases", "formula_id", m[1])).sort((a, b) => Number(a.order || 0) - Number(b.order || 0)), config);
  if (method === "POST" && m) return response(await create(tenantId, "pd_formula_phases", { ...data, formula_id: m[1] }), config);
  m = match(/^\/pd\/formulas\/([^/]+)\/phases\/reorder$/);
  if (method === "PUT" && m) { for (const [order, phaseId] of (data.phase_ids || []).entries()) await patch(tenantId, "pd_formula_phases", phaseId, { order }); return response({ success: true }, config); }
  m = match(/^\/pd\/formula-phases\/([^/]+)$/);
  if (method === "PUT" && m) return response(await patch(tenantId, "pd_formula_phases", m[1], data), config);
  if (method === "DELETE" && m) { await erase(tenantId, "pd_formula_phases", m[1]); return response({ deleted: true }, config); }
  m = match(/^\/pd\/formulas\/([^/]+)$/);
  if (method === "PUT" && m) return response(await patch(tenantId, "pd_formulas", m[1], data), config);

  const devResources = { "sample-batches": "pd_sample_batches", samples: "pd_samples", documents: "pd_documents" };
  m = match(/^\/pd\/developments\/([^/]+)\/(sample-batches|samples|documents)$/);
  if (m && method === "GET") return response(await related(tenantId, devResources[m[2]], "development_id", m[1]), config);
  if (m && method === "POST") return response(await create(tenantId, devResources[m[2]], { ...data, development_id: m[1] }), config);
  m = match(/^\/pd\/developments\/([^/]+)\/sample-batches\/([^/]+)$/);
  if (method === "PUT" && m) return response(await patch(tenantId, "pd_sample_batches", m[2], data), config);
  if (method === "DELETE" && m) { await erase(tenantId, "pd_sample_batches", m[2]); return response({ deleted: true }, config); }
  m = match(/^\/pd\/samples\/([^/]+)$/);
  if (method === "PUT" && m) return response(await patch(tenantId, "pd_samples", m[1], data), config);
  m = match(/^\/pd\/documents\/([^/]+)$/);
  if (method === "DELETE" && m) { await erase(tenantId, "pd_documents", m[1]); return response({ deleted: true }, config); }
  m = match(/^\/pd\/developments\/([^/]+)\/approval$/);
  if (method === "POST" && m) return response(await create(tenantId, "pd_approvals", { ...data, development_id: m[1] }), config);
  m = match(/^\/pd\/developments\/([^/]+)\/lab-results$/);
  if (method === "PUT" && m) return response(await patch(tenantId, "pd_developments", m[1], { lab_results: data }), config);
  m = match(/^\/pd\/developments\/([^/]+)\/cost-versions\/(v1|v2)(?:\/(submit|finalize))?$/);
  if (m && ["PUT", "POST"].includes(method)) return response(await patch(tenantId, "pd_developments", m[1], { [`cost_${m[2]}`]: data, [`cost_${m[2]}_status`]: m[3] || "DRAFT" }), config);

  if (path === "/pd/catalog" && method === "GET") return response(await all(tenantId, "pd_catalog"), config);
  if (path === "/pd/catalog" && method === "POST") return response(await create(tenantId, "pd_catalog", data), config);
  m = match(/^\/pd\/catalog\/([^/]+)\/price-history$/);
  if (method === "GET" && m) return response(await related(tenantId, "pd_catalog_price_history", "catalog_id", m[1]), config);
  m = match(/^\/pd\/catalog\/([^/]+)$/);
  if (method === "PUT" && m) {
    const old = await one(tenantId, "pd_catalog", m[1]);
    const item = await patch(tenantId, "pd_catalog", m[1], data);
    if (data.price !== undefined && data.price !== old?.price) await create(tenantId, "pd_catalog_price_history", { catalog_id: m[1], old_price: old?.price, new_price: data.price });
    return response(item, config);
  }
  if (method === "DELETE" && m) { await erase(tenantId, "pd_catalog", m[1]); return response({ deleted: true }, config); }
  if (path === "/pd/stock" && method === "GET") return response(await all(tenantId, "pd_stock"), config);
  if (path === "/pd/stock" && method === "POST") return response(await create(tenantId, "pd_stock", data), config);
  if (path === "/pd/stock/alerts" && method === "GET") {
    const items = await all(tenantId, "pd_stock");
    return response(items.filter((item) => Number(item.quantity || item.quantidade || 0) <= Number(item.minimum || item.estoque_minimo || 0)), config);
  }
  if (path === "/pd/stock/check-product" && method === "GET") {
    const item = (await all(tenantId, "pd_stock")).find((entry) => contains(entry, params.produto_nome, ["product_name", "produto_nome", "nome"]));
    return response({ available: !!item && Number(item.quantity || item.quantidade || 0) > 0, item }, config);
  }
  m = match(/^\/pd\/stock\/([^/]+)\/movements$/);
  if (method === "GET" && m) return response(await related(tenantId, "pd_stock_movements", "stock_id", m[1]), config);
  if (method === "POST" && m) {
    const movement = await create(tenantId, "pd_stock_movements", { ...data, stock_id: m[1] });
    const stock = await one(tenantId, "pd_stock", m[1]);
    const delta = Number(data.quantity || data.quantidade || 0) * (["OUT", "SAIDA", "saida"].includes(data.type || data.tipo) ? -1 : 1);
    await patch(tenantId, "pd_stock", m[1], { quantity: Number(stock?.quantity || stock?.quantidade || 0) + delta });
    return response(movement, config);
  }
  m = match(/^\/pd\/stock\/([^/]+)$/);
  if (method === "PUT" && m) return response(await patch(tenantId, "pd_stock", m[1], data), config);
  if (method === "DELETE" && m) { await erase(tenantId, "pd_stock", m[1]); return response({ deleted: true }, config); }

  const homologMap = { fornecedores: "pd_homologacao_fornecedores", mps: "pd_homologacao_mps" };
  m = match(/^\/pd\/homologacao\/(fornecedores|mps)$/);
  if (m && method === "GET") return response(await all(tenantId, homologMap[m[1]]), config);
  if (m && method === "POST") return response(await create(tenantId, homologMap[m[1]], data), config);
  m = match(/^\/pd\/homologacao\/(fornecedores|mps)\/([^/]+)$/);
  if (m && method === "PUT") return response(await patch(tenantId, homologMap[m[1]], m[2], data), config);
  if (m && method === "DELETE") { await erase(tenantId, homologMap[m[1]], m[2]); return response({ deleted: true }, config); }
  m = match(/^\/pd\/homologacao\/(fornecedores|mps)\/([^/]+)\/(aprovar|reprovar|avaliar|homologar)$/);
  if (m && method === "POST") return response(await patch(tenantId, homologMap[m[1]], m[2], { ...data, status: data.aprovado === false || m[3] === "reprovar" ? "REPROVADO" : "APROVADO" }), config);
  if (path === "/pd/homologacao/dashboard" && method === "GET") {
    const suppliers = await all(tenantId, "pd_homologacao_fornecedores");
    const materials = await all(tenantId, "pd_homologacao_mps");
    return response({ total_fornecedores: suppliers.length, fornecedores_aprovados: suppliers.filter((x) => x.status === "APROVADO").length, total_mps: materials.length, mps_aprovadas: materials.filter((x) => x.status === "APROVADO").length }, config);
  }

  m = match(/^\/pd\/requests\/([^/]+)\/(updates|pending)$/);
  if (m && method === "POST") return response(await create(tenantId, m[2] === "updates" ? "pd_updates" : "pd_pending_items", { ...data, request_id: m[1], status: data.status || "pendente" }), config);
  m = match(/^\/pd\/(updates|pending)\/([^/]+)(?:\/received)?$/);
  if (m && method === "PUT") return response(await patch(tenantId, m[1] === "updates" ? "pd_updates" : "pd_pending_items", m[2], path.endsWith("/received") ? { status: "recebido", received_at: now() } : data), config);
  if (m && method === "DELETE") { await erase(tenantId, m[1] === "updates" ? "pd_updates" : "pd_pending_items", m[2]); return response({ deleted: true }, config); }
  m = match(/^\/pd\/requests\/([^/]+)\/ficha-tecnica-ui$/);
  if (method === "GET" && m) return response((await one(tenantId, "pd_requests", m[1]))?.ficha_tecnica || {}, config);
  if (method === "PUT" && m) return response(await patch(tenantId, "pd_requests", m[1], { ficha_tecnica: data }), config);
  m = match(/^\/pd\/requests\/([^/]+)\/link-to-crm$/);
  if (method === "PUT" && m) return response(await patch(tenantId, "pd_requests", m[1], data), config);

  m = match(/^\/pd\/requests\/([^/]+)\/stability-study$/);
  if (method === "GET" && m) {
    const study = (await related(tenantId, "pd_stability_studies", "request_id", m[1]))[0] || null;
    return response(study ? { ...study, readings: await related(tenantId, "pd_stability_readings", "study_id", study.id) } : null, config);
  }
  m = match(/^\/pd\/stability\/studies\/([^/]+)\/readings$/);
  if (method === "POST" && m) return response(await create(tenantId, "pd_stability_readings", { ...data, study_id: m[1] }), config);

  if (method === "POST" && path === "/upload") {
    const file = typeof FormData !== "undefined" && data instanceof FormData ? [...data.values()].find((value) => value instanceof File) : null;
    if (!file) throw apiError(400, "Arquivo nao informado.");
    try {
      const objectRef = storageRef(firebaseStorage, `erp/${tenantId}/uploads/${id()}-${file.name}`);
      await uploadBytes(objectRef, file, { contentType: file.type || "application/octet-stream" });
      return response({ url: await getDownloadURL(objectRef), filename: file.name }, config);
    } catch {
      // Projetos Spark novos podem nao ter bucket. Mantem anexos pequenos
      // funcionais no RTDB ate o Storage ser habilitado no plano Blaze.
      if (file.size > 5 * 1024 * 1024) throw apiError(413, "Arquivo maior que 5 MB. Ative o Firebase Storage para anexos grandes.");
      const url = await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = () => reject(reader.error);
        reader.readAsDataURL(file);
      });
      const upload = await create(tenantId, "uploads", { filename: file.name, content_type: file.type, size: file.size, url });
      return response({ url: upload.url, filename: file.name, id: upload.id, storage: "database" }, config);
    }
  }

  if (method === "GET" && (/\.pdf$/.test(path) || path.endsWith("/ficha-tecnica"))) {
    return response(printableBlob("Documento Kuryos", { path, generated_at: now() }), config);
  }
  if (method === "GET" && path === "/pd/metrics") {
    const requests = await all(tenantId, "pd_requests");
    const formulas = await all(tenantId, "pd_formulas");
    return response({ total_requests: requests.length, open_requests: requests.filter((x) => !["DONE", "CANCELLED", "CONCLUIDO"].includes(x.status)).length, total_formulas: formulas.length, by_status: requests.reduce((acc, item) => ({ ...acc, [item.status || "OPEN"]: (acc[item.status || "OPEN"] || 0) + 1 }), {}) }, config);
  }

  m = match(/^\/workflow\/tasks\/([^/]+)\/decision$/);
  if (method === "PUT" && m) return response(await patch(tenantId, "workflow_tasks", m[1], { ...data, decided_at: now() }), config);
  m = match(/^\/pd\/requests\/([^/]+)\/live-documents\/([^/]+)\/versions$/);
  if (method === "GET" && m) return response((await all(tenantId, "pd_document_versions")).filter((item) => item.request_id === m[1] && item.document_type === m[2]), config);
  m = match(/^\/pd\/requests\/([^/]+)\/live-documents\/([^/]+)\/generate$/);
  if (method === "POST" && m) return response(await create(tenantId, "pd_document_versions", { ...data, request_id: m[1], document_type: m[2], generated_by: firebaseAuth.currentUser.uid }), config);
  m = match(/^\/pd\/document-versions\/([^/]+)\/diff$/);
  if (method === "GET" && m) { const current = await one(tenantId, "pd_document_versions", m[1]); return response({ current, previous: null, changes: [] }, config); }

  throw apiError(501, `Rota Firebase ainda não adaptada: ${method} ${path}`);
}

const firebaseApi = {
  defaults: { baseURL: "firebase://erpkuryos" },
  interceptors: { response: { use: () => {} } },
  request(config = {}) { return dispatch(String(config.method || "GET").toUpperCase(), config.url, config.data, config); },
  get(url, config = {}) { return dispatch("GET", url, undefined, config); },
  post(url, data, config = {}) { return dispatch("POST", url, data, config); },
  put(url, data, config = {}) { return dispatch("PUT", url, data, config); },
  patch(url, data, config = {}) { return dispatch("PATCH", url, data, config); },
  delete(url, config = {}) { return dispatch("DELETE", url, undefined, config); },
};

export default firebaseApi;
